package com.aicommerce.platform.delivery.application;
import java.util.*; import com.aicommerce.platform.delivery.domain.PlatformStableErrorCode;
public final class PlatformOperationException extends RuntimeException {private final PlatformStableErrorCode code;private final Optional<UUID> operationUuid;public PlatformOperationException(PlatformStableErrorCode code,Optional<UUID> operationUuid){super(requireLocal(code).name());this.code=code;this.operationUuid=Objects.requireNonNull(operationUuid);}public PlatformStableErrorCode code(){return code;}public Optional<UUID> operationUuid(){return operationUuid;}private static PlatformStableErrorCode requireLocal(PlatformStableErrorCode code){Objects.requireNonNull(code);return switch(code){case PLATFORM_CONTRACT_INVALID,PLATFORM_OPERATION_NOT_FOUND,PLATFORM_INVALID_OPERATION_STATE,PLATFORM_STALE_VERSION,PLATFORM_RETRY_NOT_DUE,PLATFORM_RECOVERY_NOT_DUE,PLATFORM_MAX_ATTEMPTS_EXCEEDED,PLATFORM_MAX_RECONCILIATIONS_EXCEEDED,PLATFORM_ACCOUNT_INACTIVE,PLATFORM_ACCOUNT_ENVIRONMENT_MISMATCH,PLATFORM_PROVIDER_UNSUPPORTED,PLATFORM_POLICY_REJECTED,PLATFORM_ADAPTER_UNAVAILABLE,PLATFORM_IDEMPOTENCY_CONFLICT,PLATFORM_EVIDENCE_INVALID,PLATFORM_PARENT_STATE_INVALID->code;default->throw new IllegalArgumentException("PLATFORM_CONTRACT_INVALID");};}}
